function setReminderDateTime(f,startAt,minutes,reminderAt=''){const date=reminderAt?new Date(reminderAt):new Date(new Date(startAt).getTime()-minutes*60000),parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Argentina/Buenos_Aires',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).map(p=>[p.type,p.value]));f.elements.reminderDate.value=`${parts.year}-${parts.month}-${parts.day}`;f.elements.reminderTime.value=`${parts.hour}:${parts.minute}`;}
